  function catList(cat){if(cat==='all')return [...allIds().map(id=>({id,variant:'normal'})),...allIds().map(id=>({id,variant:'shiny'})),...megas().map(id=>({id,variant:'mega'})),...megas().map(id=>({id,variant:'mega_shiny'})),...bosses().map(id=>({id,variant:'boss'})),...legs().map(id=>({id,variant:'legendary'})),...psyList()];if(cat==='shiny')return allIds().map(id=>({id,variant:'shiny'}));if(cat==='mega')return megas().map(id=>({id,variant:'mega'}));if(cat==='mega_shiny')return megas().map(id=>({id,variant:'mega_shiny'}));if(cat==='boss')return bosses().map(id=>({id,variant:'boss'}));if(cat==='legendary')return legs().map(id=>({id,variant:'legendary'}));if(cat==='psyduck')return psyList();return allIds().map(id=>({id,variant:'normal'}))}
  function key(e){return `${e.variant}:${e.id}${e.sub?':'+e.sub:''}`}
  function meta(e){const v=e.variant;if(v==='normal')return['POKÉMON','#38bdf8',false,false];if(v==='shiny')return['SHINY','#facc15',true,false];if(v==='mega')return['MEGA','#a78bfa',false,true];if(v==='mega_shiny')return['MEGA SHINY','#f472b6',true,true];if(v==='boss')return['BOSS','#ef4444',false,false];if(v==='legendary')return['LENDÁRIO','#f59e0b',false,false];if(v==='psyduck'){const map={classic:['PSYDUCK','#facc15',false,false],shiny:['PSY SHINY','#f472b6',true,false],mega:['PSY MEGA','#22d3ee',false,true],mega_shiny:['PSY MEGA SHINY','#facc15',true,true],squizo:['SQUIZO','#c084fc',true,true]};return map[e.sub]||map.classic}return['FIGURINHA','#38bdf8',false,false]}
  function nm(e){if(e.variant==='psyduck')return e.label||'Psyduck';try{return getPokeName(e.id)||`Pokémon ${e.id}`}catch(_){return `Pokémon ${e.id}`}}
